1	import Phaser from 'phaser';
2	import { BaseAbility } from './BaseAbility';
3	import type { GameSceneAPI } from './types';
4	import type PoolablePoopBase from '../objects/PoolablePoopBase';
5	import { ensureGlowDot } from '../utils/glowDot';
6	import { GUMI_PARAMS } from '../config/abilityParams';
7	
8	const HIT_R = 18;
9	
10	// 꼬리가 시작되는 Y 오프셋 (플레이어 중심 기준, 양수=아래=발 쪽)
11	const TAIL_ORIGIN_Y = 10;
12	const SWAY_AMP      = 0.28; // 흔들림 진폭 (radians)
13	
14	// 꼬리 체인: 세그먼트 수, 간격, 스케일 (지렁이 파동)
15	const NUM_SEGS   = 14;   // 꼬리 세그먼트 수 (14 × 5px = 70px)
16	const STEP_DIST  = 5;    // 세그먼트 간 거리 (px)
17	const PHASE_STEP = 0.35; // 세그먼트마다 위상 어긋남
18	// 타원형: base·tip 가늘고 5~6번째 가장 두꺼움
19	const SEG_SCALES = [0.10, 0.20, 0.30, 0.37, 0.41, 0.42, 0.41, 0.36, 0.30, 0.22, 0.15, 0.10, 0.06, 0.03];
20	
21	// 꼬리 depth (플레이어 depth 5보다 낮아야 몸통 뒤에 숨음)
22	const TAIL_DEPTH = 3;
23	
24	// 여우불 9색
25	const FOX_FIRE_COLORS = [
26	  0xff2200,  // 빨
27	  0xff7700,  // 주
28	  0xffee00,  // 노
29	  0x00cc44,  // 초
30	  0x0066ff,  // 파
31	  0x3300cc,  // 남
32	  0xaa00ff,  // 보
33	  0xffffff,  // 흰
34	  0xcccccc,  // 검(회색 대체)
35	];
36	
37	// 꼬리 등장 순서: 1번째=흰, 2~8번째=빨주노초파남보, 9번째=검
38	const TAIL_COLORS = [
39	  0xffffff,  // 1번째: 흰
40	  0xff2200,  // 2번째: 빨
41	  0xff7700,  // 3번째: 주
42	  0xffee00,  // 4번째: 노
43	  0x00cc44,  // 5번째: 초
44	  0x0066ff,  // 6번째: 파
45	  0x3300cc,  // 7번째: 남
46	  0xaa00ff,  // 8번째: 보
47	  0xcccccc,  // 9번째: 검
48	];
49	
50	// 꼬리 배치 각도: TAIL_COLORS 생성 순서에 따른 시각적 위치 고정
51	// 최종 시각 배치(왼→오): 빨(190°) 주(210°) 노(230°) 초(250°) 파(270°) 남(290°) 보(310°) 흰(330°) 검(350°)
52	// 흰(1번째 생성) → 330°,  빨(2번째) → 190°,  주(3번째) → 210°, ...
53	const TAIL_ANGLE_ORDER = [330, 190, 210, 230, 250, 270, 290, 310, 350]
54	  .map(deg => deg * Math.PI / 180);
55	
56	interface FoxFire {
57	  img: Phaser.GameObjects.Image;
58	  core: Phaser.GameObjects.Graphics;
59	  x: number;
60	  y: number;
61	  baseVx: number;
62	  speedY: number;
63	  phase: number;
64	  freq: number;
65	  trailTimer: number;
66	  color: number;
67	}
68	
69	interface TailSegImg {
70	  img: Phaser.GameObjects.Image;
71	  baseScale: number;
72	}
73	
74	interface TailObj {
75	  segs: TailSegImg[];
76	  baseAngle: number;
77	  swayPhase: number;
78	  swayFreq: number;
79	  color: number;
80	}
81	
82	/**
83	 * 구미 (UR) — 꼬리 9개 무적(기본) / 여우불 금똥 변환(특수)
84	 * 수치: GUMI_PARAMS 참조
85	 */
86	export class GumiAbility extends BaseAbility {
87	  // ── 여우불 (특수 능력) ─────────────────────────────────────────────
88	  private lastGumiScore = 0;
89	  private foxFires: FoxFire[] = [];
90	
91	  // ── 꼬리 스택 (기본 효과) ─────────────────────────────────────────
92	  private tailCount = 0;
93	  private lastTailScore = 0;
94	  private invincibleActive = false;
95	  private invincibleElapsed = 0;
96	  private tails: TailObj[] = [];
97	
98	  // ── 플레이어 depth 설정 (꼬리가 몸통 뒤에 렌더링되도록) ──────────
99	  override onCreate(api: GameSceneAPI): void {
100	    api.player.setDepth(5);
101	  }
102	
103	  // ── 꼬리 추가 ─────────────────────────────────────────────────────
104	  private _addTail(api: GameSceneAPI): void {
105	    const { scene, player } = api;
106	    ensureGlowDot(scene);
107	
108	    const i         = this.tailCount;
109	    const color     = TAIL_COLORS[i] ?? 0xffffff;
110	    const baseAngle = TAIL_ANGLE_ORDER[i] ?? (270 * Math.PI / 180);
111	    const originX   = player.x;
112	    const originY   = player.y + TAIL_ORIGIN_Y;
113	
114	    const segs: TailSegImg[] = [];
115	    for (let s = 0; s < NUM_SEGS; s++) {
116	      const img = scene.add.image(
117	        originX + Math.cos(baseAngle) * (STEP_DIST * (s + 1)),
118	        originY + Math.sin(baseAngle) * (STEP_DIST * (s + 1)),
119	        'glow_dot',
120	      )
121	        .setDepth(TAIL_DEPTH)
122	        .setBlendMode(Phaser.BlendModes.ADD)
123	        .setTint(color)
124	        .setScale(0)
125	        .setAlpha(0.92);
126	      segs.push({ img, baseScale: SEG_SCALES[s] ?? 0.08 });
127	    }
128	
129	    // 등장 애니메이션 (base → tip 순차)
130	    segs.forEach((si, idx) => {
131	      scene.tweens.add({
132	        targets: si.img,
133	        scale: si.baseScale,
134	        delay: idx * 40,
135	        duration: 300,
136	        ease: 'Back.easeOut',
137	      });
138	    });
139	
140	    this.tails.push({
141	      segs,
142	      baseAngle,
143	      swayPhase: Phaser.Math.FloatBetween(0, Math.PI * 2),
144	      swayFreq:  Phaser.Math.FloatBetween(1.4, 2.8),
145	      color,
146	    });
147	    this.tailCount++;
148	
149	    if (this.tailCount >= GUMI_PARAMS.maxTails) {
150	      this._triggerInvincibility(api);
151	    }
152	  }
153	
154	  // ── 꼬리 지렁이 파동 업데이트 (매 프레임) ────────────────────────
155	  private _updateTailPositions(api: GameSceneAPI): void {
156	    const { player, scene } = api;
157	    const time    = scene.time.now * 0.001;
158	    const originX = player.x;
159	    const originY = player.y + TAIL_ORIGIN_Y;
160	
161	    for (const tail of this.tails) {
162	      let px = originX;
163	      let py = originY;
164	
165	      for (let s = 0; s < tail.segs.length; s++) {
166	        const si = tail.segs[s];
167	        if (!si.img.active) continue;
168	
169	        // 뿌리는 진폭 0, 끝으로 갈수록 진폭 증가 (지렁이 파동)
170	        const amp   = SWAY_AMP * (s / (NUM_SEGS - 1));
171	        const sway  = Math.sin(time * tail.swayFreq + tail.swayPhase + s * PHASE_STEP) * amp;
172	        const angle = tail.baseAngle + sway;
173	
174	        px += Math.cos(angle) * STEP_DIST;
175	        py += Math.sin(angle) * STEP_DIST;
176	        si.img.setPosition(px, py);
177	      }
178	    }
179	  }
180	
181	  // ── 점수 마일스톤 ─────────────────────────────────────────────────
182	  override onScoreMilestone(score: number, api: GameSceneAPI): void {
183	    // 여우불 (특수)
184	    if (score % GUMI_PARAMS.foxFireInterval === 0 && score > this.lastGumiScore) {
185	      this.lastGumiScore = score;
186	      this.summonFoxFires(api);
187	    }
188	    // 꼬리 추가 (기본) — 무적 중 누적 금지
189	    if (score % GUMI_PARAMS.tailInterval === 0 && score > this.lastTailScore && !this.invincibleActive) {
190	      this.lastTailScore = score;
191	      this._addTail(api);
192	    }
193	  }
194	
195	  // ── 무적 발동 ─────────────────────────────────────────────────────
196	  private _triggerInvincibility(api: GameSceneAPI): void {
197	    const { player, scene } = api;
198	    this.invincibleActive  = true;
199	    this.invincibleElapsed = 0;
200	
201	    // 꼬리 확대
202	    this.tails.forEach(t => {
203	      t.segs.forEach(si => {
204	        scene.tweens.add({
205	          targets: si.img,
206	          scale: si.baseScale * 1.5,
207	          duration: 320,
208	          ease: 'Back.easeOut',
209	        });
210	      });
211	    });
212	
213	    // 9색 버스트
214	    ensureGlowDot(scene);
215	    for (let i = 0; i < 9; i++) {
216	      const angle = (i / 9) * Math.PI * 2;
217	      const spark = scene.add.image(player.x, player.y, 'glow_dot')
218	        .setDepth(210)
219	        .setBlendMode(Phaser.BlendModes.ADD)
220	        .setTint(FOX_FIRE_COLORS[i])
221	        .setScale(0.6);
222	      scene.tweens.add({
223	        targets: spark,
224	        x: player.x + Math.cos(angle) * 65,
225	        y: player.y + Math.sin(angle) * 65,
226	        scale: 0, alpha: 0, duration: 520,
227	        ease: 'Quad.easeOut',
228	        onComplete: () => spark.destroy(),
229	      });
230	    }
231	  }
232	
233	  // ── 무적 카운트다운 ───────────────────────────────────────────────
234	  private _updateInvincibility(api: GameSceneAPI): void {
235	    this.invincibleElapsed += api.scene.game.loop.delta;
236	    if (this.invincibleElapsed >= GUMI_PARAMS.invincibleDuration) {
237	      this._endInvincibility(api);
238	    }
239	  }
240	
241	  // ── 무적 종료 ─────────────────────────────────────────────────────
242	  private _endInvincibility(api: GameSceneAPI): void {
243	    const { player, scene } = api;
244	
245	    this.invincibleActive = false;
246	    player.setAlpha(1);
247	
248	    // 꼬리 사라짐
249	    this.tails.forEach(t => {
250	      t.segs.forEach(si => {
251	        scene.tweens.add({
252	          targets: si.img, alpha: 0, scale: 0,
253	          duration: 380, ease: 'Quad.easeIn',
254	          onComplete: () => si.img.destroy(),
255	        });
256	      });
257	    });
258	    this.tails       = [];
259	    this.tailCount   = 0;
260	    this.lastTailScore = api.score; // 무적 중 지나친 마일스톤 역추적 방지
261	
262	    this._spawnBreakEffect(api);
263	    this._zapAllPoops(api);
264	  }
265	
266	  // ── 무적 종료 파열 이펙트 (센티넬 방어막 파열 스타일, 황금색) ────
267	  private _spawnBreakEffect(api: GameSceneAPI): void {
268	    const { player, scene } = api;
269	    const cx = player.x;
270	    const cy = player.y;
271	
272	    scene.cameras.main.flash(200, 255, 200, 50, true);
273	
274	    // 확산 링 2겹
275	    [{ delay: 0, maxScale: 4.3 }, { delay: 80, maxScale: 3.4 }].forEach(({ delay, maxScale }) => {
276	      const ring = scene.add.graphics().setDepth(150);
277	      ring.lineStyle(2.5, 0xffcc44, 0.9);
278	      ring.strokeEllipse(0, 0, 74, 98);
279	      ring.setPosition(cx, cy);
280	      scene.tweens.add({
281	        targets: ring, scaleX: maxScale, scaleY: maxScale, alpha: 0,
282	        duration: 500, delay, ease: 'Quad.easeOut',
283	        onComplete: () => ring.destroy(),
284	      });
285	    });
286	
287	    // 내부 섬광
288	    const fill = scene.add.graphics().setDepth(149);
289	    fill.fillStyle(0xffcc44, 0.25);
290	    fill.fillEllipse(0, 0, 74, 98);
291	    fill.setPosition(cx, cy);
292	    scene.tweens.add({
293	      targets: fill, alpha: 0, duration: 180, ease: 'Quad.easeOut',
294	      onComplete: () => fill.destroy(),
295	    });
296	
297	    // 황금 파편 8개
298	    for (let i = 0; i < 8; i++) {
299	      const angle = (i / 8) * Math.PI * 2 + Phaser.Math.FloatBetween(-0.25, 0.25);
300	      const speed = Phaser.Math.FloatBetween(40, 95);
301	      const w     = Phaser.Math.Between(5, 12);
302	      const h     = Phaser.Math.Between(2, 5);
303	      const shard = scene.add.graphics().setDepth(152);
304	      shard.fillStyle(0xffcc44, 1);
305	      shard.fillRect(-w / 2, -h / 2, w, h);
306	      shard.setPosition(cx, cy);
307	      shard.setRotation(angle);
308	      scene.tweens.add({
309	        targets: shard,
310	        x: cx + Math.cos(angle) * speed,
311	        y: cy + Math.sin(angle) * speed,
312	        alpha: 0, rotation: angle + Phaser.Math.FloatBetween(-1, 1),
313	        duration: Phaser.Math.Between(270, 440), ease: 'Quad.easeOut',
314	        onComplete: () => shard.destroy(),
315	      });
316	    }
317	  }
318	
319	  // ── 반경 내 똥 전부 제거 ──────────────────────────────────────────
320	  private _zapAllPoops(api: GameSceneAPI): void {
321	    const { player, poops, scene } = api;
322	    const r  = GUMI_PARAMS.zapRadius;
323	    const r2 = r * r;
324	
325	    (poops.getChildren() as Phaser.Physics.Arcade.Sprite[])
326	      .filter(p => p.active && (p.x - player.x) ** 2 + (p.y - player.y) ** 2 <= r2)
327	      .forEach(p => (p as unknown as PoolablePoopBase).recycle());
328	
329	    ensureGlowDot(scene);
330	
331	    // 황금 확산 링 2겹
332	    for (let i = 0; i < 2; i++) {
333	      const ring = scene.add.graphics().setDepth(212);
334	      ring.lineStyle(3 - i, 0xffcc44, 0.9 - i * 0.3);
335	      ring.strokeCircle(0, 0, 20);
336	      ring.setPosition(player.x, player.y);
337	      scene.tweens.add({
338	        targets: ring, scaleX: r / 20, scaleY: r / 20, alpha: 0,
339	        delay: i * 80, duration: 560, ease: 'Quad.easeOut',
340	        onComplete: () => ring.destroy(),
341	      });
342	    }
343	
344	    // 중앙 섬광
345	    const flash = scene.add.image(player.x, player.y, 'glow_dot')
346	      .setDepth(213)
347	      .setBlendMode(Phaser.BlendModes.ADD)
348	      .setTint(0xffee88)
349	      .setScale(1.8);
350	    scene.tweens.add({
351	      targets: flash, scale: 0, alpha: 0, duration: 460,
352	      ease: 'Quad.easeOut',
353	      onComplete: () => flash.destroy(),
354	    });
355	  }
356	
357	  // ── 피격: 무적 중이면 게임오버 방지 ──────────────────────────────
358	  override onHitPoop(_api: GameSceneAPI): boolean {
359	    return this.invincibleActive;
360	  }
361	
362	  // ── 여우불 소환 ───────────────────────────────────────────────────
363	  private summonFoxFires(api: GameSceneAPI): void {
364	    const { scene, player } = api;
365	    const N = GUMI_PARAMS.foxFireCount;
366	    ensureGlowDot(scene);
367	
368	    for (let i = 0; i < N; i++) {
369	      const ringAngle = (i / N) * Math.PI * 2;
370	      const x = player.x + Math.cos(ringAngle) * 55;
371	      const y = player.y + Math.sin(ringAngle) * 55;
372	      const color = FOX_FIRE_COLORS[i];
373	
374	      const img = scene.add.image(x, y, 'glow_dot')
375	        .setDepth(200)
376	        .setBlendMode(Phaser.BlendModes.ADD)
377	        .setTint(color)
378	        .setScale(0.45);
379	
380	      const core = scene.add.graphics().setDepth(202);
381	      core.fillStyle(0xffffff, 1);
382	      core.fillCircle(0, 0, 5);
383	      core.fillStyle(color, 0.85);
384	      core.fillCircle(0, 0, 3.5);
385	      core.setPosition(x, y);
386	
387	      this.foxFires.push({
388	        img, core, x, y, color,
389	        baseVx:     Phaser.Math.FloatBetween(-3.5, 3.5),
390	        speedY:     Phaser.Math.FloatBetween(4.5, 7.5),
391	        phase:      Phaser.Math.FloatBetween(0, Math.PI * 2),
392	        freq:       Phaser.Math.FloatBetween(0.07, 0.17),
393	        trailTimer: 0,
394	      });
395	    }
396	  }
397	
398	  // ── 매 프레임 ─────────────────────────────────────────────────────
399	  override onUpdate(api: GameSceneAPI): void {
400	    this._updateTailPositions(api);
401	    if (this.invincibleActive) this._updateInvincibility(api);
402	
403	    if (this.foxFires.length === 0) return;
404	
405	    const { scene } = api;
406	    const activePoops = api.poops.getChildren().filter(
407	      p => (p as Phaser.Physics.Arcade.Sprite).active,
408	    ) as Phaser.Physics.Arcade.Sprite[];
409	
410	    const remaining: FoxFire[] = [];
411	
412	    for (const fire of this.foxFires) {
413	      fire.trailTimer++;
414	      fire.x += fire.baseVx + Math.sin(fire.phase + fire.trailTimer * fire.freq) * 6;
415	      fire.y -= fire.speedY;
416	      fire.img.setPosition(fire.x, fire.y);
417	      fire.core.setPosition(fire.x, fire.y);
418	
419	      if (fire.trailTimer % 3 === 0) {
420	        const trail = scene.add.image(fire.x, fire.y, 'glow_dot')
421	          .setDepth(199)
422	          .setBlendMode(Phaser.BlendModes.ADD)
423	          .setTint(fire.color)
424	          .setScale(0.22);
425	        scene.tweens.add({
426	          targets: trail, scale: 0, alpha: 0, duration: 200,
427	          ease: 'Quad.easeOut',
428	          onComplete: () => trail.destroy(),
429	        });
430	      }
431	
432	      if (fire.y < -30 || fire.x < -30 || fire.x > 430) {
433	        fire.img.destroy();
434	        fire.core.destroy();
435	        continue;
436	      }
437	
438	      let hit = false;
439	      for (const poop of activePoops) {
440	        const dx = fire.x - poop.x;
441	        const dy = fire.y - poop.y;
442	        if (dx * dx + dy * dy < HIT_R * HIT_R) {
443	          const px = poop.x;
444	          const py = poop.y;
445	          (poop as unknown as PoolablePoopBase).recycle();
446	          api.spawnGoldPoopAt(px, py);
447	          this.spawnHitFlash(px, py, scene);
448	          fire.img.destroy();
449	          fire.core.destroy();
450	          hit = true;
451	          break;
452	        }
453	      }
454	
455	      if (!hit) remaining.push(fire);
456	    }
457	
458	    this.foxFires = remaining;
459	  }
460	
461	  private spawnHitFlash(x: number, y: number, scene: Phaser.Scene): void {
462	    for (let i = 0; i < 6; i++) {
463	      const angle = (i / 6) * Math.PI * 2;
464	      const spark = scene.add.image(x, y, 'glow_dot')
465	        .setDepth(201)
466	        .setBlendMode(Phaser.BlendModes.ADD)
467	        .setTint(0xffd700)
468	        .setScale(0.3);
469	      scene.tweens.add({
470	        targets: spark,
471	        x: x + Math.cos(angle) * 25,
472	        y: y + Math.sin(angle) * 25,
473	        scale: 0, alpha: 0, duration: 300,
474	        ease: 'Quad.easeOut',
475	        onComplete: () => spark.destroy(),
476	      });
477	    }
478	  }
479	
480	  override onDestroy(api: GameSceneAPI): void {
481	    if (this.invincibleActive) {
482	      api.player.setAlpha(1);
483	    }
484	    api.player.setDepth(0); // player depth 원복
485	    this.foxFires.forEach(f => { f.img.destroy(); f.core.destroy(); });
486	    this.foxFires = [];
487	    this.tails.forEach(t => t.segs.forEach(si => si.img.destroy()));
488	    this.tails = [];
489	  }
490	}
