  // ── 꼬리 번호별 패시브 효과 적용 ──────────────────────────────
  // i = 현재 추가되는 꼬리의 0-indexed 번호 (0=1번째, 1=2번째 ...)
  if (i % 3 === 0) {
    // 1, 4, 7번째: 특수 똥 수집 +5점
    this.specialBonus += GUMI_PARAMS.tailSpecialBonus;
  } else if (i % 3 === 1) {
    // 2, 5, 8번째: 이동 속도 +5px/s
    player.addPermanentSpeed(GUMI_PARAMS.tailSpeedBonus);
  } else {
    // 3, 6, 9번째: 일반 똥 소환 -1개
    this.spawnReduction += 1;
  }

  this.tailCount++;

  if (this.tailCount >= GUMI_PARAMS.maxTails) {
    this._triggerInvincibility(api);
  }
}

