  maxShields: 3,            // 최대 보호막 개수
} as const;

export const SENTINEL_DESC = {
  basicEffect: `시작 시 보호막 ${SENTINEL_PARAMS.startShields}개 보유 (피격 흡수 시 주변 똥 전기로 제거)`,
